/**
 * A React Native scaffold writes every module its GENERATED code imports.
 *
 * The injector synthesizes the app's default bond files deterministically: the
 * auth and HTTP bonds import `../config.js`, the i18n bond imports
 * `../locales/en/ui.js`, and the bonds smoke test imports the same files. Those
 * imports are generated by shared code, so nothing in the injector can make them
 * disappear — the scaffold has to produce the files.
 *
 * Until 2026-11-23 `createReactNativeAppProject` did not: it wrote only its own
 * App/screens/bonds and never ran the shared `config.ts` / `locales/` copier the
 * web scaffolds use, so a fresh Expo app failed `npm run build` with
 * `TS2307: Cannot find module '../config.js'` (and the i18n locale file) — a
 * dangling import the scaffold itself created. It also pre-wrote a
 * `src/bonds/index.ts` stub that `setupBonds()` was expected to fill, so the
 * injector kept that stub and the app had no `setupProviders()`.
 *
 * The test generates the bond files for a React Native project and asserts every
 * relative import in the generated sources resolves to a file the scaffold
 * wrote. On the old output the shared modules are missing and it fails.
 */
import { mkdir, mkdtemp, readFile, rm, stat, writeFile } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { dirname, join, relative } from 'node:path'

import { afterEach, beforeEach, describe, expect, it } from 'vitest'

import { synthesizeAppProjectFiles } from '../injector.js'
import { loadRegistry } from '../registry.js'
import { createReactNativeAppProject } from '../scaffold.js'

/** The packages a React Native app's generated bond files cover. */
const MOLECULES = ['@molecule/app-auth', '@molecule/app-http', '@molecule/app-i18n']

/** Every relative module specifier in `source` (`./x.js`, `../x.js`). */
function relativeImports(source: string): string[] {
  return [...source.matchAll(/from\s+'(\.[^']+)'|import\s+'(\.[^']+)'/g)].map(
    (match) => match[1] ?? match[2]!,
  )
}

/**
 * Whether a relative specifier names something that exists on disk.
 *
 * A TS/ESM specifier ends in `.js` while the source file is `.ts`/`.tsx`, so the
 * bare `./x.js` spelling is translated back before the existence check.
 */
async function resolves(
  fromFile: string,
  specifier: string,
  generated: ReadonlySet<string> = new Set(),
): Promise<boolean> {
  const base = join(dirname(fromFile), specifier.replace(/\.js$/, ''))
  for (const candidate of [base, `${base}.ts`, `${base}.tsx`, `${base}.d.ts`]) {
    // A sibling in the SAME synthesis is written in the same injection run.
    if (generated.has(candidate)) return true
    try {
      if ((await stat(candidate)).isFile()) return true
    } catch (_error) {
      // Not this spelling — try the next one.
    }
  }
  return false
}

describe('react-native scaffold writes the modules its generated code imports', () => {
  let projectPath: string

  beforeEach(async () => {
    projectPath = await mkdtemp(join(tmpdir(), 'mlcl-rn-scaffold-'))
    await mkdir(join(projectPath, 'src'), { recursive: true })
    await writeFile(
      join(projectPath, 'package.json'),
      JSON.stringify({
        name: 'rn-app',
        molecule: { projectType: 'app', framework: 'react-native' },
      }),
    )
    await createReactNativeAppProject(projectPath, 'rn-app')
  })

  afterEach(async () => {
    await rm(projectPath, { recursive: true, force: true })
  })

  it('writes config.ts and the locales tree the default bonds import', async () => {
    expect(await resolves(join(projectPath, 'src', 'bonds', 'auth.ts'), '../config.js')).toBe(true)
    expect(
      await resolves(join(projectPath, 'src', 'bonds', 'i18n.ts'), '../locales/en/ui.js'),
    ).toBe(true)

    // config.ts is the native app's: Expo's public env var, not Vite's import.meta.env
    const config = await readFile(join(projectPath, 'src', 'config.ts'), 'utf-8')
    expect(config).toContain('EXPO_PUBLIC_API_URL')
    expect(config).not.toContain('import.meta.env?.VITE_API_URL')
  })

  it('gets the format scripts and formatter config every web scaffold has', async () => {
    const pkg = JSON.parse(await readFile(join(projectPath, 'package.json'), 'utf-8'))
    expect(pkg.scripts['format:check']).toMatch(/^prettier --check /)
    expect(pkg.scripts.format).toMatch(/^prettier --write /)
    expect(await resolves(join(projectPath, 'x'), './.prettierrc')).toBe(true)
    expect(await resolves(join(projectPath, 'x'), './.prettierignore')).toBe(true)
  })

  it('writes no bonds/index.ts stub, so the injector owns setupProviders()', async () => {
    expect(await resolves(join(projectPath, 'src', 'App.tsx'), './bonds/index.js')).toBe(false)
  })

  it('every relative import in the generated bonds and their test resolves', async () => {
    const generated = synthesizeAppProjectFiles([], MOLECULES, projectPath, loadRegistry())
    expect(generated.length).toBeGreaterThan(0)
    const generatedPaths = new Set(generated.map((file) => file.targetPath))

    const unresolved: string[] = []
    for (const file of generated) {
      for (const specifier of relativeImports(file.content ?? '')) {
        if (!(await resolves(file.targetPath, specifier, generatedPaths))) {
          unresolved.push(`${relative(projectPath, file.targetPath)} → ${specifier}`)
        }
      }
    }
    expect(unresolved).toEqual([])
  })
})
